    16  typedef struct {
    17      const char *data;
    18      size_t size;
    19  } xmlFuzzEntityInfo;
    20
    21  /* Single static instance for now */
    22  static struct {
    23      /* Original data */
    24      const char *data;
    25      size_t size;
    26
    27      /* Remaining data */
    28      const char *ptr;
    29      size_t remaining;
    30
    31      /* Buffer for unescaped strings */
    32      char *outBuf;
    33      char *outPtr; /* Free space at end of buffer */
    34
    35      xmlHashTablePtr entities; /* Maps URLs to xmlFuzzEntityInfos */
    36
    37      /* The first entity is the main entity. */
    38      const char *mainUrl;
    39      xmlFuzzEntityInfo *mainEntity;
    40  } fuzzData;
    41
    42  /**
    43   * xmlFuzzErrorFunc:
    44   *
    45   * An error function that simply discards all errors.
    46   */
    47  void
    48  xmlFuzzErrorFunc(void *ctx ATTRIBUTE_UNUSED, const char *msg ATTRIBUTE_UNUSED,
    49                   ...) {
    50  }
