    52  /**
    53   * xmlFuzzDataInit:
    54   *
    55   * Initialize fuzz data provider.
    56   */
    57  void
    58  xmlFuzzDataInit(const char *data, size_t size) {
    59      fuzzData.data = data;
    60      fuzzData.size = size;
    61      fuzzData.ptr = data;
    62      fuzzData.remaining = size;
    63
    64      fuzzData.outBuf = xmlMalloc(size + 1);
    65      fuzzData.outPtr = fuzzData.outBuf;
    66
    67      fuzzData.entities = xmlHashCreate(8);
    68      fuzzData.mainUrl = NULL;
    69      fuzzData.mainEntity = NULL;
    70  }
    71
    72  static void
    73  xmlFreeEntityEntry(void *value, const xmlChar *name) {
    74      xmlFree(value);
    75  }
    76
    77  /**
    78   * xmlFuzzDataFree:
    79   *
    80   * Cleanup fuzz data provider.
    81   */
    82  void
    83  xmlFuzzDataCleanup(void) {
    84      xmlFree(fuzzData.outBuf);
    85      xmlHashFree(fuzzData.entities, xmlFreeEntityEntry);
    86  }
