    88  /**
    89   * xmlFuzzReadInt:
    90   * @size:  size of string in bytes
    91   *
    92   * Read an integer from the fuzz data.
    93   */
    94  int
    95  xmlFuzzReadInt() {
    96      int ret;
    97
    98      if (fuzzData.remaining < sizeof(int))
    99          return(0);
   100      memcpy(&ret, fuzzData.ptr, sizeof(int));
   101      fuzzData.ptr += sizeof(int);
   102      fuzzData.remaining -= sizeof(int);
   103
   104      return ret;
   105  }
   106
   107  /**
   108   * xmlFuzzReadRemaining:
   109   * @size:  size of string in bytes
   110   *
   111   * Read remaining bytes from fuzz data.
   112   */
   113  const char *
   114  xmlFuzzReadRemaining(size_t *size) {
   115      const char *ret = fuzzData.ptr;
   116
   117      *size = fuzzData.remaining;
   118      fuzzData.ptr += fuzzData.remaining;
   119      fuzzData.remaining = 0;
   120
   121      return(ret);
   122  }
   123
   124  /*
   125   * xmlFuzzWriteString:
   126   * @out:  output file
   127   * @str:  string to write
   128   *
   129   * Write a random-length string to file in a format similar to
   130   * FuzzedDataProvider. Backslash followed by newline marks the end of the
   131   * string. Two backslashes are used to escape a backslash.
   132   */
   133  void
   134  xmlFuzzWriteString(FILE *out, const char *str) {
   135      for (; *str; str++) {
   136          int c = (unsigned char) *str;
   137          putc(c, out);
   138          if (c == '\\')
   139              putc(c, out);
   140      }
   141      putc('\\', out);
   142      putc('\n', out);
   143  }
   144
   145  /**
   146   * xmlFuzzReadString:
   147   * @size:  size of string in bytes
   148   *
   149   * Read a random-length string from the fuzz data.
   150   *
   151   * The format is similar to libFuzzer's FuzzedDataProvider but treats
   152   * backslash followed by newline as end of string. This makes the fuzz data
   153   * more readable. A backslash character is escaped with another backslash.
   154   *
   155   * Returns a zero-terminated string or NULL if the fuzz data is exhausted.
   156   */
   157  const char *
   158  xmlFuzzReadString(size_t *size) {
   159      const char *out = fuzzData.outPtr;
   160
   161      while (fuzzData.remaining > 0) {
   162          int c = *fuzzData.ptr++;
   163          fuzzData.remaining--;
   164
   165          if ((c == '\\') && (fuzzData.remaining > 0)) {
   166              int c2 = *fuzzData.ptr;
   167
   168              if (c2 == '\n') {
   169                  fuzzData.ptr++;
   170                  fuzzData.remaining--;
   171                  *size = fuzzData.outPtr - out;
   172                  *fuzzData.outPtr++ = '\0';
   173                  return(out);
   174              }
   175              if (c2 == '\\') {
   176                  fuzzData.ptr++;
   177                  fuzzData.remaining--;
   178              }
   179          }
   180
   181          *fuzzData.outPtr++ = c;
   182      }
   183
   184      if (fuzzData.outPtr > out) {
   185          *size = fuzzData.outPtr - out;
   186          *fuzzData.outPtr++ = '\0';
   187          return(out);
   188      }
   189
   190      return(NULL);
   191  }
