   193  /*
   194   * A custom entity loader that writes all external DTDs or entities to a
   195   * single file in the format expected by xmlFuzzEntityLoader.
   196   */
   197  xmlParserInputPtr
   198  xmlFuzzEntityRecorder(const char *URL, const char *ID,
   199                        xmlParserCtxtPtr ctxt) {
   200      xmlParserInputPtr in;
   201      static const int chunkSize = 16384;
   202      int len;
   203
   204      in = xmlNoNetExternalEntityLoader(URL, ID, ctxt);
   205      if (in == NULL)
   206          return(NULL);
   207
   208      if (fuzzData.entities == NULL) {
   209          fuzzData.entities = xmlHashCreate(4);
   210      } else if (xmlHashLookup(fuzzData.entities,
   211                               (const xmlChar *) URL) != NULL) {
   212          return(in);
   213      }
   214
   215      do {
   216          len = xmlParserInputBufferGrow(in->buf, chunkSize);
   217          if (len < 0) {
   218              fprintf(stderr, "Error reading %s\n", URL);
   219              xmlFreeInputStream(in);
   220              return(NULL);
   221          }
   222      } while (len > 0);
   223
   224      xmlFuzzWriteString(stdout, URL);
   225      xmlFuzzWriteString(stdout, (char *) xmlBufContent(in->buf->buffer));
   226
   227      xmlFreeInputStream(in);
   228
   229      xmlHashAddEntry(fuzzData.entities, (const xmlChar *) URL, NULL);
   230
   231      return(xmlNoNetExternalEntityLoader(URL, ID, ctxt));
   232  }
   233
   234  /**
   235   * xmlFuzzReadEntities:
   236   *
   237   * Read entities like the main XML file, external DTDs, external parsed
   238   * entities from fuzz data.
   239   */
   240  void
   241  xmlFuzzReadEntities(void) {
   242      size_t num = 0;
   243
   244      while (1) {
   245          const char *url, *entity;
   246          size_t urlSize, entitySize;
   247          xmlFuzzEntityInfo *entityInfo;
   248
   249          url = xmlFuzzReadString(&urlSize);
   250          if (url == NULL) break;
   251
   252          entity = xmlFuzzReadString(&entitySize);
   253          if (entity == NULL) break;
   254
   255          if (xmlHashLookup(fuzzData.entities, (xmlChar *)url) == NULL) {
   256              entityInfo = xmlMalloc(sizeof(xmlFuzzEntityInfo));
   257              entityInfo->data = entity;
   258              entityInfo->size = entitySize;
   259
   260              xmlHashAddEntry(fuzzData.entities, (xmlChar *)url, entityInfo);
